import java.util.concurrent.*;public class Driver {public static void main(String[]a)throws InterruptedException{ExecutorService pool=Executors.newFixedThreadPool(3);for(int i=1;i<=6;i++){final int id=i;pool.submit(()->System.out.println("Task #"+id+" executing on "+Thread.currentThread().getName()));}pool.shutdown();pool.awaitTermination(5,TimeUnit.SECONDS);System.out.println("All thread pool tasks completed successfully.");}}
